package com.governai.decision; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.UUID; @Entity @Table(name="retrieved_evidence") public class RetrievedEvidence {@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@Column(name="decision_request_id",nullable=false) private UUID decisionRequestId;@Enumerated(EnumType.STRING)@JdbcTypeCode(SqlTypes.NAMED_ENUM)@Column(name="source_type",nullable=false,columnDefinition="evidence_source_enum")private EvidenceSource sourceType;@Column(name="policy_section_id")private UUID policySectionId;@Column(name="regulatory_section_id")private UUID regulatorySectionId;@Column(name="source_title",length=255)private String sourceTitle;@Column(name="section_reference",length=100)private String sectionReference;@Column(name="evidence_text",nullable=false,columnDefinition="text")private String evidenceText;@Column(name="relevance_score",precision=6,scale=5)private BigDecimal relevanceScore;@Enumerated(EnumType.STRING)@JdbcTypeCode(SqlTypes.NAMED_ENUM)@Column(name="evidence_type",columnDefinition="evidence_type_enum")private EvidenceType evidenceType;@Column(name="created_at",nullable=false)private OffsetDateTime createdAt;@PrePersist void create(){if(createdAt==null)createdAt=OffsetDateTime.now();}public UUID getId(){return id;}public UUID getDecisionRequestId(){return decisionRequestId;}public void setDecisionRequestId(UUID v){decisionRequestId=v;}public EvidenceSource getSourceType(){return sourceType;}public void setSourceType(EvidenceSource v){sourceType=v;}public UUID getPolicySectionId(){return policySectionId;}public void setPolicySectionId(UUID v){policySectionId=v;}public UUID getRegulatorySectionId(){return regulatorySectionId;}public void setRegulatorySectionId(UUID v){regulatorySectionId=v;}public String getSourceTitle(){return sourceTitle;}public void setSourceTitle(String v){sourceTitle=v;}public String getSectionReference(){return sectionReference;}public void setSectionReference(String v){sectionReference=v;}public String getEvidenceText(){return evidenceText;}public void setEvidenceText(String v){evidenceText=v;}public BigDecimal getRelevanceScore(){return relevanceScore;}public void setRelevanceScore(BigDecimal v){relevanceScore=v;}public EvidenceType getEvidenceType(){return evidenceType;}public void setEvidenceType(EvidenceType v){evidenceType=v;}public OffsetDateTime getCreatedAt(){return createdAt;}}
